"""Optimal quota-constrained follow-up planning and probe certificates."""
from protocols import probe_script


def _empty_plan():
    return {'resolved': 0, 'cost': 0, 'assignments': []}


def solve(context, active):
    requests = context['requests']
    offers = context['offers']
    leases = context['leases']
    if not requests or not offers:
        return _empty_plan()

    # Collect the listed request/offer pairs that satisfy every static
    # assignment precondition.  Activity itself was frozen earlier.
    cross = []
    used_offers = set()
    for offer_id, offer in offers.items():
        capacity = offer['capacity']
        if capacity <= 0:
            continue
        service = offer['service']
        network = offer['network']
        first = int(network.network_address)
        last = int(network.broadcast_address)
        offer_time = offer['time']
        listed = []
        for request_id in offer['requests']:
            if not active.get(request_id):
                continue
            request = requests[request_id]
            if request['service'] != service:
                continue
            if request['at'] > offer_time:
                continue
            if offer_time >= leases[request['lease']]['end']:
                continue
            if first <= request['address'] <= last:
                listed.append(request_id)
        if listed:
            used_offers.add(offer_id)
            for request_id in listed:
                cross.append((request_id, offer_id))
    if not cross:
        return _empty_plan()

    import networkx as nx

    request_ids = sorted({request_id for request_id, _ in cross})
    offer_ids = sorted(used_offers)

    request_quotas = context['request_quotas']
    offer_quotas = context['offer_quotas']
    request_paths = context['request_paths']
    offer_paths = context['offer_paths']

    # A quota node whose capacity is at least the maximum possible number of
    # assignments in its subtree can never constrain a plan.  Contract those
    # nodes away; this keeps the flow network dramatically smaller when the
    # quota forests are loose while preserving every binding bound.
    request_counts = {node_id: 0 for node_id in request_quotas}
    for request_id in request_ids:
        request_counts[requests[request_id]['group']] += 1
    for node_id in sorted(request_quotas,
                          key=lambda name: len(request_paths[name]),
                          reverse=True):
        parent = request_quotas[node_id]['parent']
        if parent is not None:
            request_counts[parent] += request_counts[node_id]
    request_binding = {
        node_id: request_quotas[node_id]['capacity'] < request_counts[node_id]
        for node_id in request_quotas
    }

    offer_capacities = {node_id: 0 for node_id in offer_quotas}
    for offer_id in offer_ids:
        offer_capacities[offers[offer_id]['group']] += offers[offer_id]['capacity']
    for node_id in sorted(offer_quotas,
                          key=lambda name: len(offer_paths[name]),
                          reverse=True):
        parent = offer_quotas[node_id]['parent']
        if parent is not None:
            offer_capacities[parent] += offer_capacities[node_id]
    offer_binding = {
        node_id: offer_quotas[node_id]['capacity'] < offer_capacities[node_id]
        for node_id in offer_quotas
    }

    def nearest_binding(paths, binding, node_id, include_self):
        path = paths[node_id]
        for position, ancestor in enumerate(path):
            if not include_self and position == 0:
                continue
            if binding[ancestor]:
                return ancestor
        return None

    request_nearest = {
        node_id: nearest_binding(request_paths, request_binding, node_id, True)
        for node_id in request_quotas
    }
    offer_nearest = {
        node_id: nearest_binding(offer_paths, offer_binding, node_id, True)
        for node_id in offer_quotas
    }

    next_node = 1
    source = 0
    request_quota_node = {}
    for node_id in request_quotas:
        if request_binding[node_id]:
            request_quota_node[node_id] = next_node
            next_node += 1
    request_node = {}
    for request_id in request_ids:
        request_node[request_id] = next_node
        next_node += 1
    offer_node = {}
    for offer_id in offer_ids:
        offer_node[offer_id] = next_node
        next_node += 1
    offer_quota_node = {}
    for node_id in offer_quotas:
        if offer_binding[node_id]:
            offer_quota_node[node_id] = next_node
            next_node += 1
    sink = next_node
    next_node += 1

    graph = nx.DiGraph()
    graph.add_nodes_from(range(next_node))

    # Request forest: source/ancestor -> binding node, with the arc entering a
    # binding node carrying that node's subtree capacity.
    for node_id in request_quotas:
        if not request_binding[node_id]:
            continue
        ancestor = nearest_binding(request_paths, request_binding,
                                   node_id, False)
        upper = source if ancestor is None else request_quota_node[ancestor]
        graph.add_edge(upper, request_quota_node[node_id],
                       capacity=request_quotas[node_id]['capacity'], weight=0)

    # Attach each relevant request to its nearest binding quota ancestor, or
    # directly to the source when its whole ancestor chain is nonbinding.
    for request_id in request_ids:
        group = requests[request_id]['group']
        ancestor = request_nearest[group]
        upper = source if ancestor is None else request_quota_node[ancestor]
        graph.add_edge(upper, request_node[request_id],
                       capacity=1, weight=0)

    # Assignment arcs.  Each carries the offer's per-assignment cost.
    for request_id, offer_id in cross:
        graph.add_edge(request_node[request_id], offer_node[offer_id],
                       capacity=1, weight=offers[offer_id]['cost'])

    # Per-offer capacity, then the binding part of the offer forest, flowing
    # toward the sink.
    for offer_id in offer_ids:
        offer = offers[offer_id]
        group = offer['group']
        ancestor = offer_nearest[group]
        lower = sink if ancestor is None else offer_quota_node[ancestor]
        graph.add_edge(offer_node[offer_id], lower,
                       capacity=offer['capacity'], weight=0)
    for node_id in offer_quotas:
        if not offer_binding[node_id]:
            continue
        ancestor = nearest_binding(offer_paths, offer_binding, node_id, False)
        lower = sink if ancestor is None else offer_quota_node[ancestor]
        graph.add_edge(offer_quota_node[node_id], lower,
                       capacity=offer_quotas[node_id]['capacity'], weight=0)

    # Maximum cardinality is just the maximum flow value of this network.
    max_count = int(nx.maximum_flow_value(graph, source, sink))
    if max_count <= 0:
        return _empty_plan()

    # Keep only nodes that lie on some source-sink path.  Other nodes cannot
    # carry flow in any feasible maximum-cardinality flow.
    def reachable(start, reverse):
        seen = {start}
        stack = [start]
        if reverse:
            while stack:
                node = stack.pop()
                for previous in graph.predecessors(node):
                    if previous not in seen:
                        edge = graph.get_edge_data(previous, node)
                        if edge and edge.get('capacity', 0) > 0:
                            seen.add(previous)
                            stack.append(previous)
        else:
            while stack:
                node = stack.pop()
                for following in graph.successors(node):
                    if following not in seen:
                        edge = graph.get_edge_data(node, following)
                        if edge and edge.get('capacity', 0) > 0:
                            seen.add(following)
                            stack.append(following)
        return seen

    from_source = reachable(source, False)
    to_sink = reachable(sink, True)
    keep = from_source & to_sink
    if len(keep) != next_node:
        graph.remove_nodes_from([node for node in graph if node not in keep])

    graph.nodes[source]['demand'] = -max_count
    graph.nodes[sink]['demand'] = max_count
    _cost, flow = nx.network_simplex(graph)
    del graph

    script_cache = {}
    assignments = []
    total_cost = 0
    for request_id, offer_id in cross:
        request_flow = flow.get(request_node[request_id])
        if not request_flow:
            continue
        if request_flow.get(offer_node[offer_id], 0) <= 0:
            continue
        offer = offers[offer_id]
        total_cost += offer['cost']
        request = requests[request_id]
        kind = context['services'][request['service']]
        script = script_cache.get(kind)
        if script is None:
            script = probe_script(kind)
            script_cache[kind] = script
        assignments.append({'request': request_id, 'offer': offer_id,
                            'send': list(script[0]),
                            'finish': list(script[1])})

    assignments.sort(key=lambda item: item['request'])
    return {'resolved': len(assignments), 'cost': total_cost,
            'assignments': assignments}
